    dp = [[0]*(60+1) for _ in range(2)]
    dp[0][0] = dp[1][0] = 1
    for i in range(N): 
        for j in range(55, -1, -1):
            dp[0][j+red_balls[i][0]] += dp[0][j] if red_balls[i][2] == 1 else 0
            dp[1][j+blue_balls[i][0]] += dp[1][j] if blue_balls[i][2] == 1 else 0
    return max(dp[0][60], dp[1][60])
``` 

